module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

reg [1:0] state;
reg [1:0] count;
reg clk_div_int;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        count <= 0;
        clk_div_int <= 0;
    end else begin
        case (state)
            2'b00: begin
                if (count == MUL2_DIV_CLK - 1) begin
                    count <= 0;
                    clk_div_int <= ~clk_div_int;
                end else begin
                    count <= count + 1;
                end
            end
            2'b01: begin
                if (count == MUL2_DIV_CLK / 2 - 1) begin
                    count <= 0;
                    clk_div_int <= ~clk_div_int;
                end else begin
                    count <= count + 1;
                end
            end
            default: begin
                state <= 0;
            end
        endcase
        state <= state + 1;
    end
end

assign clk_div = clk_div_int;

endmodule
